# RUN: llvm-mca -mtriple=aarch64 -mcpu=cortex-a78 -instruction-tables < %s | FileCheck %s

# Based on Cortex-A78 Software Optimization Guide
# s3.11 FP data processing instructions

# FP absolute value
fabs	s0, s1

# FP arithmetic
fadd	s0, s1, s2
fsub	s0, s1, s2

# FP compare
fccmp	s0, s1, #0, eq
fccmpe	s0, s1, #0, eq

# FP divide, H-form
fdiv	h0, h1, h2

# FP divide, S-form
fdiv	s0, s1, s2

# FP divide, D-form
fdiv	d0, d1, d2

# FP min/max
fmin	s0, s1, s2
fminnm	s0, s1, s2
fmax	s0, s1, s2
fmaxnm	s0, s1, s2

# FP multiply
fmul	s0, s1, s2
fnmul	s0, s1, s2
fmul	d0, d1, d2
fnmul	d0, d1, d2

# FP multiply accumulate
fmadd	s0, s1, s2, s3
fmsub	s0, s1, s2, s3
fnmadd	s0, s1, s2, s3
fnmsub	s0, s1, s2, s3

# FP negate
fneg	s0, s1
fneg	d0, d1

# FP round to integral
frinta	s0, s1
frinti	s0, s1
frintm	s0, s1
frintn	s0, s1
frintp	s0, s1
frintx	s0, s1
frintz	s0, s1

# FP select
fcsel	s0, s1, s2, pl
fcsel	d0, d1, d2, pl

# FP square root, H-form
fsqrt	h0, h1

# FP square root, S-form
fsqrt	s0, s1

# FP square root, D-form
fsqrt	d0, d1

